<script setup lang="ts">import{ref,onMounted,computed}from 'vue';import{lab,load}from '../stores/research';import*as runs from '../api/runs';import type{Run}from '../types/domain';import{fmt,pct,ratio}from '../utils/format';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import RateStrips from '../components/RateStrips.vue';const current=ref<Run|null>(null),{error,execute}=useTask(),r=computed(()=>current.value?.result);async function init(){await load();const x=lab.runs.find(x=>x.status==='completed');current.value=x?await runs.detail(x.id):null}onMounted(()=>execute(init));</script><template><PageHeading index="01" title="先分层，再讨论总体率。" text="封装方法与成功率之间的关联，先经过边际结构的核对。"/><ErrorNotice :message="error" @retry="execute(init)"/><div class="overview-spread"><section class="lead-sheet"><div class="sheet-top"><p class="eyebrow">LATEST FROZEN RECORD</p><RouterLink to="/configure">建立核对研究 ↗</RouterLink></div><template v-if="r&&current"><h2>{{r.input_snapshot.study.name}}</h2><p>{{r.input_snapshot.study.description}}</p><RateStrips :rows="r.strata"/><RouterLink class="underlined" :to="'/results?run='+current.id">展开分层与完整精确分布 →</RouterLink></template><div v-else class="empty">先建立2个以上分层，填写a/b/c/d，再提交冻结计算。<RouterLink to="/sources">打开底稿 →</RouterLink></div></section><aside class="overview-margin"><p class="eyebrow">ONE POOLED TABLE IS NOT ALL</p><template v-if="r"><div class="margin-number"><small>总体率 A / B</small><strong>{{pct(r.pooled.rate_a)}}<i>/ {{pct(r.pooled.rate_b)}}</i></strong></div><div class="margin-number"><small>粗 OR / 分层 MH OR</small><strong>{{ratio(r.pooled.odds_ratio)}}<i>/ {{ratio(r.adjusted_or)}}</i></strong></div><p>CMH {{fmt(r.cmh)}} · 条件双侧p {{r.exact.p_display}}</p></template><blockquote>样本在哪一层，<br>和多少样本一样重要。</blockquote><p>共同OR是加权摘要。未检验层间同质性，未做随机化因果识别。</p><div class="inventory"><b>{{lab.studies.length}}</b>份试验底稿 <b>{{lab.runs.filter(r=>r.status==='completed').length}}</b>份已完成核对</div></aside></div><section class="reading-path"><article><b>01 / 底稿</b><h3>四格，先对方向</h3><p>a/b为A成功/失败；c/d为B成功/失败。层在试验前声明。</p></article><article><b>02 / 条件</b><h3>每层边际固定</h3><p>超几何分布逐层卷积；精确p按均值距离双侧计算。</p></article><article><b>03 / 复验</b><h3>把线索留给试片</h3><p>负责人核对说明后，阅读者导出完整支持域与指纹。</p></article></section></template>
